using namespace private_input::activity;
static Json word(const Json&a,const std::string&t){for(const auto&w:a.at("entries").items)if(w.at("text").str()==t)return w;return {};}
int main(){try{require(sodium_init()>=0,"sodium");const std::string actor="11111111-1111-4111-8111-111111111111";auto archive=emptyLearning(),sequential=emptyRecent();std::vector<RecentLocalDelta>deltas;unsigned checks=0;auto check=[&](bool b,const char*m){++checks;require(b,m);};
 auto select=[&](const std::string&t,uint64_t day){auto before=archive;archive=recordLearning(archive,"he cheng",t,actor);sequential=confirmRecentDelta(sequential,before,archive,actor,day,day);auto d=confirmedRecentLocalDelta(word(before,t),word(archive,t),actor,day);if(d)deltas.push_back(*d);};
 select("合成",100);select("合成",100);auto partial=applyRecentLocalDeltas(emptyRecent(),archive,deltas,actor,100);select("其他",100);select("合成",101);select("合成",101);auto batch=applyRecentLocalDeltas(emptyRecent(),archive,deltas,actor,101);check(batch.dump()==sequential.dump(),"repeated same word and cross-day batch equals sequential confirmation");check(applyRecentLocalDeltas(batch,archive,deltas,actor,101).dump()==batch.dump(),"ambiguous committed save replay cannot double day counts");check(applyRecentLocalDeltas(partial,archive,deltas,actor,101).dump()==batch.dump(),"partial covered counter watermarks clip already applied units");
 auto before=archive;for(auto&w:archive["entries"].items)if(w.at("text").str()=="合成"){w["generation"]=1;w["deleted"]=true;w["counts"]=Json::object();}sequential=confirmRecentDelta(sequential,before,archive,actor,101,101);check(applyRecentLocalDeltas(emptyRecent(),archive,deltas,actor,101).dump()==sequential.dump(),"authoritative tombstone retires unflushed prior generation deltas");
 before=archive;for(auto&w:archive["entries"].items)if(w.at("text").str()=="合成"){w["generation"]=2;w["deleted"]=false;}archive=recordLearning(archive,"he cheng","合成",actor);sequential=confirmRecentDelta(sequential,before,archive,actor,101,101);check(!confirmedRecentLocalDelta(word(before,"合成"),word(archive,"合成"),actor,101),"restore generation follows existing no invented dated unit rule");select("合成",101);check(applyRecentLocalDeltas(emptyRecent(),archive,deltas,actor,101).dump()==sequential.dump(),"restore followed by fresh selection matches sequential dates");
 auto recovered=mergeLegacyRecent(emptyRecent(),archive,101);for(const auto&e:recovered.at("entries").items)check(e.at("buckets").items.empty(),"restart without durable date deltas recovers undated only");check(recentProjection(recovered).dump()==mergeLearning(emptyLearning(),archive).dump(),"undated recovery preserves all authoritative counters and generations");std::cout<<"PASS "<<checks<<" recent derived batch checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
